mapper.update:
UPDATE private
SET is_read = 1
WHERE sender = #{senderId}
AND receiver = #{currentUserId}

mapper.select:
SELECT * FROM ( SELECT p.id, p.content, p.sender AS senderId, p.receiver AS receiverId, p.create_time AS createTime, s.username AS senderName, r.username AS receiverName FROM `private` p LEFT JOIN `user` s ON p.sender = s.id LEFT JOIN `user` r ON p.receiver = r.id WHERE p.sender = #{currentUserId}
AND p.receiver = #{receiver}
AND p.is_read = #{isRead}
UNION ALL
SELECT p.id, p.content, p.sender AS senderId, p.receiver AS receiverId, p.create_time AS createTime, s.username AS senderName, r.username AS receiverName FROM `private` p LEFT JOIN `user` s ON p.sender = s.id LEFT JOIN `user` r ON p.receiver = r.id WHERE p.receiver = #{currentUserId}
AND p.sender = #{sender}
AND p.is_read = #{isRead}
) t ORDER BY t.createTime ASC
